import { describe, it, expect } from "vitest";
import { nextGeneration, type Cell } from "./game-of-life.js";

function expectCells(actual: Cell[], expected: Cell[]): void {
  const sort = (cells: Cell[]) =>
    [...cells].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  expect(sort(actual)).toEqual(sort(expected));
}

describe("Game of Life - nextGeneration", () => {
  it.todo("should return empty array for empty input -- []");
  it.todo(
    "should kill a single isolated cell -- [(0,0)] becomes []",
  );
  it.todo(
    "should apply underpopulation rule -- [(0,1), (1,1)] becomes []",
  );
  it.todo(
    "should apply survival rule -- [(0,1), (1,1), (2,1), (1,0)] becomes [(1,0), (1,1)]",
  );
  it.todo(
    "should apply overpopulation rule -- 3x3 block [(0,0),(1,0),(2,0),(0,1),(1,1),(2,1),(0,2),(1,2),(2,2)] becomes [(0,0),(2,0),(0,2),(2,2)]",
  );
  it.todo(
    "should apply reproduction rule -- [(0,2), (1,2), (0,1)] becomes [(0,2), (1,2), (0,1), (1,1)]",
  );
  it.todo(
    "should preserve block still life -- [(0,0), (1,0), (0,1), (1,1)] unchanged",
  );
  it.todo(
    "should evolve blinker horizontally -- [(0,0), (0,1), (0,2)] becomes [(-1,1), (0,1), (1,1)]",
  );
  it.todo(
    "should evolve blinker back vertically -- [(-1,1), (0,1), (1,1)] becomes [(0,0), (0,1), (0,2)]",
  );
});

