function next(cells) {
  const live = new Set(cells.map(([x,y]) => x+','+y));
  const neighbors = new Map();
  for (const [x,y] of cells) {
    for (let dx=-1;dx<=1;dx++) for (let dy=-1;dy<=1;dy++) {
      if (dx===0&&dy===0) continue;
      const k = (x+dx)+','+(y+dy);
      neighbors.set(k, (neighbors.get(k)||0)+1);
    }
  }
  const next = new Set();
  for (const [k,c] of neighbors) {
    const [x,y]=k.split(',').map(Number);
    const alive = live.has(k);
    if (alive && (c===2||c===3)) next.add(k);
    if (!alive && c===3) next.add(k);
  }
  for (const k of live) {
    if (!neighbors.has(k)) {} // isolated dies
  }
  return [...next].map(k=>k.split(',').map(Number));
}
// survival
console.log('survival', next([[0,1],[1,1],[2,1],[1,0]]));
// overpopulation 3x3
const g = [];
for(let x=0;x<=2;x++) for(let y=0;y<=2;y++) g.push([x,y]);
console.log('3x3', next(g));
// reproduction
console.log('repro', next([[0,2],[1,2],[0,1]]));
"

